VALUES ('meeting-8p-60m', 'Q3 Core Infrastructure & Real-Time AI Inference Architecture Review', 'October 10, 2026 • 2:00 PM EST', '2026-10-10T14:00:00Z', 3600, '60m', 'google-meet', 'Engineering', 'Comprehensive 60-minute technical sign-off with 8 cross-functional leads on the real-time AI inference pipeline. The team validated 42% latency reduction via 8-bit quantization and speculative decoding, multi-region failover (<1.4s recovery), strict zero-data retention in RAM, sub-second HLS share-clips, and confirmed the Thursday 4-phase canary rollout.', '["Approved Thursday 4-stage canary deployment schedule: 5% at 09:00 UTC, 25% at 11:00 UTC, 100% by 15:00 UTC with automated rollback if P99 > 600ms.", "Standardized on quantized 8-bit streaming diarization and 70B+3B speculative decoding over NVLink, achieving 48 tokens/sec at $0.09/meeting-hour.", "Enforced strict ephemeral tmpfs RAM buffering with 12s maximum lifecycle and automated memory scrubbing assertions in CI for SOC2 compliance.", "Adopted client-side structured JSON entity rendering for instantaneous template switching without extra LLM round-trips.", "Standardized sub-second CloudFront HLS byte-range manifests for public share clips with pre-sanitized PII redaction."]'::jsonb, '{"executive-brief": {"title": "Executive Brief", "description": "High-level summary of strategic decisions, resource requirements, and organizational impact.", "sections": [{"title": "Strategic Outcomes", "items": ["Real-time AI inference latency cut by 42% (first-token under 18ms for diarization; P99 delivery under 450ms).", "Inference unit economics improved dramatically: reduced from $0.42 to $0.09 per meeting hour (86% gross margin at $29/seat tier).", "Commercial SLA established: 90-second turnaround guarantee for post-meeting executive briefs communicated to top 20 enterprise clients."]}, {"title": "Risk Mitigation & Compliance", "items": ["Zero critical or high findings in NCC Group third-party penetration test.", "Automated PII scrubbing eliminates credit cards, SSNs, API keys, and passwords before Kafka ingestion.", "Active-active multi-region failover between us-east-1 and us-west-2 verified with 1.4-second recovery in chaos testing."]}, {"title": "Rollout Schedule", "items": ["Thursday 09:00 UTC: 5% canary deployment with Datadog APM live tracing.", "Thursday 11:00 UTC: 25% scale; Thursday 15:00 UTC: 100% global traffic cutover.", "Dedicated SRE and Customer Operations war room live on Slack throughout deployment."]}]}, "engineering-arch": {"title": "Engineering & Architecture", "description": "Technical deep-dive on pipelines, infrastructure sizing, latency budgets, and failover specs.", "sections": [{"title": "Inference Pipeline & Diarization", "items": ["Audio frames chunked in 250ms windows via WebRTC edge ingest proxy.", "Acoustic diarization embeddings extracted in <18ms per window with 98.4% attribution accuracy.", "VRAM footprint: 340 MB per stream; 50 concurrent streams packed per NVIDIA L4/A10G GPU.", "Speculative decoding: 3B draft model paired with 70B target model over NVLink, yielding 48 tokens/sec throughput."]}, {"title": "Resilience & Failover Specifications", "items": ["Cross-region Route53 latency routing triggers if 3 consecutive 500ms probes fail or error rate > 2%.", "Client IndexedDB audio cache guarantees zero dropped syllables during 1.4s reconnect.", "Automatic canary rollback triggered if P99 latency exceeds 600ms for >90s or error rate > 0.5%."]}, {"title": "Security Architecture & Data Privacy", "items": ["Raw PCM buffers stored solely in ephemeral tmpfs RAM disks, zeroed within 12 seconds.", "PII scrubbing runs on CPU worker nodes prior to Kafka topic persistence.", "Public clip sharing utilizes CloudFront HLS byte-range manifests with pre-masked transcript projections."]}]}, "sales-discovery": {"title": "Sales & Enterprise Readiness", "description": "Value proposition, enterprise objection handling, and customer SLA commitments.", "sections": [{"title": "Enterprise Selling Points", "items": ["Guaranteed 90-second executive summary turnaround after meeting conclusion.", "Instantaneous view switching (Sales BANT, Executive, Jira Action Items) with zero delay.", "High-virality share-clips with sub-second generation and no-login required for external prospects."]}, {"title": "Security Objections Addressed", "items": ["Zero data retention for raw voice: audio never written to persistent disk or cloud storage.", "SOC2 Type II compliance ready, GDPR right-to-be-forgotten speaker tombstone supported within 24 hours.", "Complete tenant isolation via HMAC-signed webhooks and PostgreSQL row-level security."]}]}, "one-on-one": {"title": "Team Alignment & Ownership", "description": "Cross-functional ownership matrix and operational handoffs.", "sections": [{"title": "Departmental Ownership", "items": ["Backend (Marcus): Staging canary deployment configs, Route53 thresholds, Prometheus alerts.", "AI Research (Maya): Grounding citation threshold verification, 8-bit model weights release.", "Product Design (Elena): Mobile breakpoints, keyboard accessibility (Space, J, L, C shortcuts).", "Infrastructure (David): Warm GPU pool provisioning, cross-region replication checks.", "Security (Priya): Terraform diff review, PII test validation, formal SOC2 sign-off.", "Data Platform (Sam): Kafka consumer lag monitoring, RAM zeroing assertions in CI.", "Customer Operations (Zoe): Enterprise customer communications, help center documentation."]}]}, "customer-success": {"title": "Customer Success & Operations", "description": "Customer communication plans, support war-room staffing, and feedback tracking.", "sections": [{"title": "Customer Communications", "items": ["Notify top 20 pilot enterprise accounts about the 90-second SLA turnaround guarantee.", "Publish help center guide explaining the one-click template switcher.", "Support war room staffed on Slack from 08:30 UTC through Thursday rollout."]}, {"title": "Customer Satisfaction Telemetry", "items": ["Monitor copy-to-clipboard actions and public clip shares as primary value indicators.", "Track section-level thumbs up/down votes to identify prompt drift or edge-case hallucinations."]}]}}'::jsonb, NULL)
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, overview = EXCLUDED.overview, templates = EXCLUDED.templates;





