itle": "Account Ownership", "description": "Internal responsibilities.", "sections": [{"title": "Next Steps", "items": ["Zoe to deliver customized pilot agreement by Friday."]}]}, "customer-success": {"title": "Pilot Onboarding", "description": "Implementation timeline.", "sections": [{"title": "Milestones", "items": ["November 1st pilot launch with 50 pilot advisors.", "Weekly check-in cadence with Acme IT project manager."]}]}}'::jsonb, NULL)
