INSERT INTO public.action_items (id, meeting_id, text, assignee_id, assignee_name, due_date, completed, timestamp_seconds, formatted_time) VALUES ('act-8p-01', 'meeting-8p-60m', 'Finalize staging canary deployment configs, verify Route53 failover thresholds, and validate Prometheus alert rules', 'spk-3', 'Marcus Thorne', 'Wednesday, Oct 14', FALSE, 2780, '46:20') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.action_items (id, meeting_id, text, assignee_id, assignee_name, due_date, completed, timestamp_seconds, formatted_time) VALUES ('act-8p-02', 'meeting-8p-60m', 'Verify grounding citation confidence threshold on 70B model and publish quantized 8-bit weights to container registry', 'spk-2', 'Dr. Maya Lin', 'Wednesday, Oct 14', FALSE, 2810, '46:50') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.action_items (id, meeting_id, text, assignee_id, assignee_name, due_date, completed, timestamp_seconds, formatted_time) VALUES ('act-8p-03', 'meeting-8p-60m', 'Verify mobile responsive breakpoints, keyboard shortcut tooltips (Space, J, L, C), and polish scrubber animations', 'spk-4', 'Elena Rostova', 'Wednesday, Oct 14', TRUE, 2840, '47:20') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.action_items (id, meeting_id, text, assignee_id, assignee_name, due_date, completed, timestamp_seconds, formatted_time) VALUES ('act-8p-04', 'meeting-8p-60m', 'Provision warm idle GPU nodes in us-east-1 and us-west-2, verify database cross-region replication latency', 'spk-5', 'David Kalu', 'Wednesday, Oct 14', FALSE, 2870, '47:50') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.action_items (id, meeting_id, text, assignee_id, assignee_name, due_date, completed, timestamp_seconds, formatted_time) VALUES ('act-8p-05', 'meeting-8p-60m', 'Review edge proxy Terraform diffs, sign off on PII redaction test results, and issue formal SOC2 authorization', 'spk-6', 'Priya Sharma', 'Wednesday, Oct 14', FALSE, 2900, '48:20') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.action_items (id, meeting_id, text, assignee_id, assignee_name, due_date, completed, timestamp_seconds, formatted_time) VALUES ('act-8p-06', 'meeting-8p-60m', 'Monitor Kafka consumer lag and add automated memory-zeroing integration assertions in CI test suite', 'spk-7', 'Sam Chen', 'Wednesday, Oct 14', FALSE, 2930, '48:50') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.action_items (id, meeting_id, text, assignee_id, assignee_name, due_date, completed, timestamp_seconds, formatted_time) VALUES ('act-8p-07', 'meeting-8p-60m', 'Notify top 20 enterprise pilot clients of 90s turnaround SLA and staff the Slack release war room at 08:30 UTC', 'spk-8', 'Zoe Washington', 'Thursday, Oct 15', FALSE, 2960, '49:20') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.action_items (id, meeting_id, text, assignee_id, assignee_name, due_date, completed, timestamp_seconds, formatted_time) VALUES ('act-8p-08', 'meeting-8p-60m', 'Oversee Thursday canary traffic progression (5% -> 25% -> 100%) and verify executive telemetry dashboard', 'spk-1', 'Alex Vance', 'Thursday, Oct 15', FALSE, 3020, '50:20') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.highlights (id, meeting_id, title, quote, speaker_name, start_time, formatted_time, category) VALUES ('hl-8p-01', 'meeting-8p-60m', '42% Latency Drop with Quantized Model', 'The latency reduction is significant—almost 42% faster time-to-first-token—without any measurable degradation on our evaluation benchmarks.', 'Dr. Maya Lin', 42, '00:42', 'milestone') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.highlights (id, meeting_id, title, quote, speaker_name, start_time, formatted_time, category) VALUES ('hl-8p-02', 'meeting-8p-60m', 'Instant Client-Side Template Switching', 'When a user toggles templates in the UI, we don''t need to re-run the entire LLM prompt. The client simply renders the structured entity graph through that template''s specific presentation lens!', 'Dr. Maya Lin', 660, '11:00', 'insight') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.highlights (id, meeting_id, title, quote, speaker_name, start_time, formatted_time, category) VALUES ('hl-8p-03', 'meeting-8p-60m', 'Sub-Second HLS Share Clips Without Re-Encoding', 'Under the hood, we don''t re-encode the entire video file to create a clip. We generate an HLS byte-range manifest slice on CloudFront, so clip creation is sub-second.', 'Marcus Thorne', 1170, '19:30', 'insight') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.highlights (id, meeting_id, title, quote, speaker_name, start_time, formatted_time, category) VALUES ('hl-8p-04', 'meeting-8p-60m', 'Unit Economics: $0.09 per Meeting Hour', 'With our quantized 8-bit models and speculative decoding, our inference cost per meeting hour is down from $0.42 to $0.09, giving us an 86% gross margin.', 'Marcus Thorne', 2020, '33:40', 'milestone') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.highlights (id, meeting_id, title, quote, speaker_name, start_time, formatted_time, category) VALUES ('hl-8p-05', 'meeting-8p-60m', 'Automated Canary Rollback Thresholds', 'Automatic rollback triggers if P99 latency exceeds 600ms for more than 90 seconds, or if error rate surpasses 0.5% in any 60-second window.', 'David Kalu', 3080, '51:20', 'decision') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-001', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 0, 20, '00:00', 'Good afternoon everyone. Thanks for jumping on. Today we have our mandatory sixty-minute architecture review for our real-time AI inference pipeline. We need full consensus across Product, AI, Backend, SRE, Security, Design, Data, and Ops before our canary rollout on Thursday.', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-002', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 20, 41, '00:20', 'Thanks Alex. On the backend side, we''ve benchmarked the new streaming gateway. Our primary goal today is locking down the multi-region failover and agreeing on the P99 latency threshold for concurrent audio transcription and summarization.', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-003', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 41, 62, '00:41', 'From the AI research perspective, we completed the evaluation of the quantized 8-bit model versus the full precision checkpoint. The latency reduction is significant—almost 42% faster time-to-first-token—without any measurable degradation on our evaluation benchmarks.', TRUE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-004', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 62, 83, '01:02', 'And from design, we want to make sure the UI reflects these latency improvements gracefully. When the transcription stream encounters jitter or packet loss, the user shouldn''t see jittery jumps in the UI.', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-005', 'meeting-8p-60m', 'spk-5', 'David Kalu', 83, 104, '01:23', 'From infrastructure and SRE, my primary concern is cold starts and GPU memory footprint during traffic spikes. If we fail over to our secondary US-East cluster, we must guarantee we don''t breach our four-nines uptime target.', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-006', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 104, 125, '01:44', 'Security and compliance also has three non-negotiables: end-to-end encryption in transit, strict zero-data retention agreements for customer audio buffers, and automated PII redaction before vector embeddings are stored.', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-007', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 125, 146, '02:05', 'On the data platform side, our streaming Kafka connectors and vector pipeline are ready. We need to verify that the PII tokenization happens before the text chunks hit our Kafka topic, not after.', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-008', 'meeting-8p-60m', 'spk-8', 'Zoe Washington', 146, 167, '02:26', 'And representing Customer Ops: enterprise clients have been asking for SLA commitments on meeting summary turnaround time. If a meeting ends, they expect the executive brief ready within ninety seconds.', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-009', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 167, 188, '02:47', 'That ninety-second window is an explicit customer promise in our enterprise tier. Let''s make sure today''s architecture supports that consistently. Marcus, walk us through the current system diagram.', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-010', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 188, 209, '03:08', 'Sure. The user''s audio stream enters our WebRTC edge ingest proxy. Audio frames are chunked into 250-millisecond windows and sent to our streaming ASR workers.', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-011', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 209, 230, '03:29', 'Those workers generate interim word hypotheses with confidence scores. Once an utterance boundary is detected, the normalized transcript segment is emitted to both the live client WebSocket and our internal event bus.', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-012', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 230, 251, '03:50', 'The utterance boundary detection is key. In the previous build, we had issues with speaker overlap where two people talking at once created fragmented segments.', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-013', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 251, 272, '04:11', 'We''ve now integrated our acoustic diarization model that computes speaker embeddings alongside the speech-to-text token stream. That gives us 98.4% speaker attribution accuracy.', TRUE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-014', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 272, 293, '04:32', 'That''s huge Maya. In our user testing, users were frustrated when a speaker switch didn''t register until five words into a sentence. Does the diarization happen in real time?', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-015', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 293, 314, '04:53', 'Yes, the embedding extraction takes under 18 milliseconds per window. So the UI gets the speaker identity simultaneously with the first word of the utterance.', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-016', 'meeting-8p-60m', 'spk-5', 'David Kalu', 314, 335, '05:14', 'What does that look like in terms of GPU VRAM per concurrent stream, Maya?', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-017', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 335, 356, '05:35', 'Each stream allocates approximately 340 megabytes of VRAM. On an NVIDIA L4 or A10G instance with 24 gigabytes of VRAM, we can safely pack 50 concurrent streams per GPU with safety headroom.', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-018', 'meeting-8p-60m', 'spk-5', 'David Kalu', 356, 377, '05:56', 'Fifty streams per GPU is acceptable, but during peak US business hours—say 10 AM Eastern—we anticipate up to 6,000 concurrent active calls. That requires at least 120 GPUs dedicated solely to diarization and ASR.', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-019', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 377, 398, '06:17', 'We should also factor in our auto-scaling warm pool. If an enterprise starts a 500-person all-hands call, our Kubernetes cluster needs to scale pods in under 30 seconds.', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-020', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 398, 419, '06:38', 'That''s why we implemented the warm idle buffer in EKS. We always keep 15% spare capacity running so we don''t hit cold start penalties when spinning up new node groups.', FALSE, 'Pipeline Overview & Streaming ASR') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-021', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 419, 440, '06:59', 'Before we go deeper into scaling, let''s address the audio buffer retention in memory. David, where are the raw PCM audio buffers stored during transcription?', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-022', 'meeting-8p-60m', 'spk-5', 'David Kalu', 440, 461, '07:20', 'They exist in ephemeral tmpfs RAM disks mounted on the ingestion pod. No audio ever touches persistent disk or S3 buckets unless the customer explicitly enabled cloud audio recording.', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-023', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 461, 482, '07:41', 'And what is the memory lifetime before the buffer is overwritten?', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-024', 'meeting-8p-60m', 'spk-5', 'David Kalu', 482, 503, '08:02', 'Immediately upon segment finalization and ACK from the summarization engine, the memory block is zeroed out. The maximum retention in RAM is 12 seconds in case of network retry.', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-025', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 503, 524, '08:23', 'Good. Make sure we have an automated test asserting the memory scrub in our CI pipeline so we can show audit logs to SOC2 and ISO auditors.', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-026', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 524, 545, '08:44', 'I will add an integration assertion in our data test suite that validates memory zeroing on worker termination.', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-027', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 545, 566, '09:05', 'Excellent. Now let''s talk about the summarization pipeline. Once the meeting reaches 15, 30, or 60 minutes, how are we generating the rolling summaries and the final executive brief?', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-028', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 566, 587, '09:26', 'We have a two-stage summarization engine. Stage one is a rolling map-reduce worker that creates semantic chapter summaries every five minutes.', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-029', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 587, 607, '09:47', 'And stage two runs at meeting conclusion. It pulls all chapter summaries plus key flagged utterances and passes them to our fine-tuned 70B model with a specialized system prompt for meeting intelligence.', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-030', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 607, 628, '10:07', 'How does the template switcher interact with that? For example, if a user switches from Executive Brief to Sales Discovery or Engineering Architecture?', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-031', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 628, 649, '10:28', 'That''s the beauty of our structured output schema. We extract universal meeting entities—decisions, blockers, numerical commitments, action items, and objections—into an intermediate JSON representation.', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-032', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 649, 670, '10:49', 'When a user toggles templates in the UI, we don''t need to re-run the entire LLM prompt. The client simply renders the structured entity graph through that template''s specific presentation lens!', TRUE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-033', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 670, 691, '11:10', 'That is brilliant! That means template switching is instantaneous in the UI. No loading spinner or extra API cost for the user.', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-034', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 691, 712, '11:31', 'That is a massive UX differentiator against competing tools where switching views takes eight to ten seconds of re-generation.', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-035', 'meeting-8p-60m', 'spk-8', 'Zoe Washington', 712, 733, '11:52', 'Our enterprise customers will love that. Sales reps especially want to switch to a BANT format for Salesforce sync, while engineering managers want the Action Item and Jira view.', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-036', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 733, 754, '12:13', 'From the data storage standpoint, storing that structured JSON graph in PostgreSQL with JSONB is very lightweight—typically under 45 kilobytes per one-hour meeting.', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-037', 'meeting-8p-60m', 'spk-5', 'David Kalu', 754, 775, '12:34', 'What happens if the primary inference cluster in us-east-1 encounters a degradation or network partition?', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-038', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 775, 796, '12:55', 'We have an active-active fallback configured in us-west-2. The health check daemon probes the inference gateway every 500 milliseconds.', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-039', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 796, 817, '13:16', 'If three consecutive heartbeat probes fail or error rate exceeds 2%, traffic dynamically reroutes to us-west-2 via AWS Route53 latency routing.', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-040', 'meeting-8p-60m', 'spk-5', 'David Kalu', 817, 838, '13:37', 'Have we tested the failover under simulated load? What is the client experience during the switch?', FALSE, 'GPU Memory & Template Engine') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-041', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 838, 859, '13:58', 'We ran a chaos test last Tuesday. In-flight WebSocket connections reconnected within 1.4 seconds. The frontend audio buffer held the packets in local IndexedDB so not a single syllable of transcript was lost.', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-042', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 859, 880, '14:19', 'Did the user see any jarring flicker or disconnection banner in the client?', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-043', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 880, 901, '14:40', 'A subtle yellow reconnection dot appeared in the status bar for about two seconds, then switched back to green. No modal or interruption.', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-044', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 901, 922, '15:01', 'That matches our design spec for resilient connection states. We want to avoid loud error alerts unless disconnection persists beyond five seconds.', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-045', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 922, 943, '15:22', 'Let''s discuss the PII masking layer. Where does the named entity recognition and redaction occur?', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-046', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 943, 964, '15:43', 'It runs directly in the stream processing pipeline right after diarization. We use a hybrid regex and fine-tuned BERT model running on CPU nodes.', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-047', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 964, 985, '16:04', 'What entity types are masked by default?', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-048', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 985, 1006, '16:25', 'Credit card numbers, social security numbers, API tokens, passwords, and personal phone numbers. Names and company emails can be preserved or pseudonymized depending on enterprise organization policy.', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-049', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 1006, 1027, '16:46', 'What about compliance with European GDPR requests for right-to-be-forgotten? If a participant requests their transcript deleted, how is that handled?', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-050', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 1027, 1048, '17:07', 'Because each transcript segment is tagged with a unique speakerId, we can execute a soft-tombstone or cryptographic purge on that speaker''s dialogue across all indexed documents within 24 hours.', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-051', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 1048, 1069, '17:28', 'That completely satisfies our legal commitments for EU enterprise expansion. Great design, Sam.', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-052', 'meeting-8p-60m', 'spk-8', 'Zoe Washington', 1069, 1090, '17:49', 'I want to bring up the share-clip feature. In Fathom, one of our highest virality loops is when an executive or salesperson cuts a 30-second snippet of a meeting and shares it with external partners.', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-053', 'meeting-8p-60m', 'spk-8', 'Zoe Washington', 1090, 1111, '18:10', 'How fast does clip generation happen, and can recipients view the video and interactive transcript without creating an account?', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-054', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 1111, 1132, '18:31', 'Yes! We designed the Share Clip modal to let users highlight any sentence in the transcript, adjust the start and end handles, and instantly preview the clip.', TRUE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-055', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 1132, 1153, '18:52', 'The generated public link has a secure token. Unauthenticated viewers get a clean, branded playback interface with synchronized transcript scrolling.', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-056', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 1153, 1174, '19:13', 'Under the hood, we don''t re-encode the entire video file to create a clip. We generate an HLS byte-range manifest slice on CloudFront, so clip creation is sub-second.', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-057', 'meeting-8p-60m', 'spk-5', 'David Kalu', 1174, 1195, '19:34', 'That saves tremendous cloud compute and egress costs. We''re serving clips directly from edge caches rather than triggering FFmpeg transcoding jobs.', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-058', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 1195, 1215, '19:55', 'And the AI can auto-suggest clips! When the model detects an executive consensus or a critical product decision, it flags a ''Smart Moment'' with recommended start and end timestamps.', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-059', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 1215, 1236, '20:15', 'Let''s ensure that in our UI, those Smart Highlights are prominently featured alongside the transcript with a one-click ''Share Clip'' button.', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-060', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 1236, 1257, '20:36', 'Already in the Figma components Alex. We have category badges for ''Decision'', ''Risk'', ''Insight'', and ''Action''.', FALSE, 'Failover, Chaos Tests & PII Masking') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-061', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 1257, 1278, '20:57', 'Do public share clips respect PII redaction? If someone creates a clip of a section containing redacted info, is there any leak?', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-062', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 1278, 1299, '21:18', 'No, the share manifest reads from the sanitized transcript projection. The redacted tokens are permanently masked before any public URL token is minted.', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-063', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 1299, 1320, '21:39', 'Perfect. Security approves that flow.', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-064', 'meeting-8p-60m', 'spk-5', 'David Kalu', 1320, 1341, '22:00', 'Now let''s examine our observability stack. How are we monitoring inference latency and error rates in production?', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-065', 'meeting-8p-60m', 'spk-5', 'David Kalu', 1341, 1362, '22:21', 'We have Datadog APM tracing every single request from the edge proxy to the transcription workers and LLM inference endpoints.', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-066', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 1362, 1383, '22:42', 'Our key Prometheus metrics include audio_chunk_ingest_lag_ms, asr_time_to_first_token_ms, and summary_generation_duration_seconds.', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-067', 'meeting-8p-60m', 'spk-5', 'David Kalu', 1383, 1404, '23:03', 'What are our P95 and P99 latency alerts set to?', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-068', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 1404, 1425, '23:24', 'For streaming transcript delivery, P95 is 280 milliseconds, and P99 is 450 milliseconds. If P99 exceeds 600 milliseconds over a 3-minute window, an automated PagerDuty alert fires to our on-call SRE.', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-069', 'meeting-8p-60m', 'spk-8', 'Zoe Washington', 1425, 1446, '23:45', 'What happens if a Zoom or Google Meet API webhook delivers delayed metadata?', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-070', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 1446, 1467, '24:06', 'We have an idempotency deduplication key on every webhook payload. If Zoom delivers meeting metadata late, our reconciler attaches the metadata to the existing session without duplicate records.', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-071', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 1467, 1488, '24:27', 'That resolves the duplicate meeting cards bug we saw two sprints ago. Fantastic work.', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-072', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 1488, 1509, '24:48', 'Let''s also review the speculative decoding engine we implemented for our summarization models.', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-073', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 1509, 1530, '25:09', 'By running a compact 3B draft model alongside our 70B target model, we achieve a 2.4x speedup during summary generation without altering the output text by even one character.', TRUE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-074', 'meeting-8p-60m', 'spk-5', 'David Kalu', 1530, 1551, '25:30', 'Is the draft model co-located on the same GPU node, or does it run over NVLink?', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-075', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 1551, 1572, '25:51', 'It''s co-located on the same node utilizing tensor parallelism over NVLink. Communication overhead is negligible—under 3 milliseconds per batch.', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-076', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 1572, 1593, '26:12', 'That explains why our batch inference throughput increased from 18 tokens per second to over 48 tokens per second in yesterday''s benchmark!', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-077', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 1593, 1614, '26:33', 'That directly translates to meeting summaries arriving in under 40 seconds instead of 90 seconds. That is huge for user retention.', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-078', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 1614, 1635, '26:54', 'From a design perspective, how should we show the summary generation progress to the user while they wait in the post-meeting workspace?', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-079', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 1635, 1656, '27:15', 'Should we display a step-by-step progress indicator like ''Transcribing audio... Extracting action items... Generating Executive Brief'' or a pulsing shimmer skeleton?', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-080', 'meeting-8p-60m', 'spk-8', 'Zoe Washington', 1656, 1677, '27:36', 'Definitely step-by-step progress! Users feel much more confident when they see the exact milestones completing in real time rather than a generic spinner.', FALSE, 'Share Clips & Speculative Decoding') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-081', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 1677, 1698, '27:57', 'I agree with Zoe. Showing ''4 of 4 participants identified'', ''12 action items parsed'', and ''Executive Brief assembled'' builds trust in the AI''s accuracy.', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-082', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 1698, 1719, '28:18', 'I''ll make sure our workspace components include the interactive status stepper for newly processed calls.', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-083', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 1719, 1740, '28:39', 'Let''s discuss action item extraction. Sometimes speakers make tentative suggestions like ''Maybe we should consider updating the docs'' versus firm commitments like ''I will update the docs by Friday''.', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-084', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 1740, 1761, '29:00', 'We solved that by introducing a confidence classifier on modal verbs. Utterances with definitive modal verbs like ''will'', ''going to'', and explicit time anchors are tagged as high-confidence Action Items.', TRUE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-085', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 1761, 1782, '29:21', 'Tentative suggestions are categorized as ''Ideas / Discussion Points'' rather than polluting the Action Items checklist.', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-086', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 1782, 1802, '29:42', 'That is such an important distinction. Nobody wants their task list flooded with hypothetical brainstorming remarks.', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-087', 'meeting-8p-60m', 'spk-8', 'Zoe Washington', 1802, 1823, '30:02', 'Can users check off action items directly in the Fathom UI, and do those checked states sync to integrations?', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-088', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 1823, 1844, '30:23', 'Yes, the action items have working checkboxes. When checked, the state toggles immediately with optimistic UI updates and can trigger a webhook to Slack, Asana, or Linear.', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-089', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 1844, 1865, '30:44', 'We also store the assigneeId and the exact timestampSeconds of the transcript where the task was assigned. Clicking the action item jumps right to that moment in the recording!', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-090', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 1865, 1886, '31:05', 'That''s one of my favorite features in the workspace. If someone asks ''Wait, did I really agree to take that on?'', you just click the timestamp and hear the exact context.', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-091', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 1886, 1907, '31:26', 'Are there any data isolation risks with multi-tenant action item synchronization?', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-092', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 1907, 1928, '31:47', 'For instance, if customer A connects to Slack, could a webhook payload inadvertently route to customer B''s workspace?', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-093', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 1928, 1949, '32:08', 'No, each webhook is signed with an HMAC-SHA256 signature using a tenant-isolated secret key. Furthermore, our database uses row-level security with tenant_id partitioned tables.', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-094', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 1949, 1970, '32:29', 'That satisfies our SOC2 tenant isolation requirements. Thank you Marcus.', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-095', 'meeting-8p-60m', 'spk-5', 'David Kalu', 1970, 1991, '32:50', 'Let''s review our cost modeling. At 50,000 meeting hours per month, what is our projected AWS and GPU inference bill?', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-096', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 1991, 2012, '33:11', 'With our quantized 8-bit models and speculative decoding, our inference cost per meeting hour is down from $0.42 to $0.09.', TRUE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-097', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 2012, 2033, '33:32', 'Nine cents per hour?! That gives us an 86% gross margin on our $29/seat enterprise pricing tier!', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-098', 'meeting-8p-60m', 'spk-8', 'Zoe Washington', 2033, 2054, '33:53', 'That''s phenomenal. It also gives us room to offer generous free tier limits to drive viral adoption.', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-099', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 2054, 2075, '34:14', 'And if we switch our batch summary workloads to AWS Trainium or Inferentia2 instances next quarter, we can shave another 25% off that figure.', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-100', 'meeting-8p-60m', 'spk-5', 'David Kalu', 2075, 2096, '34:35', 'I''ve already set up an Inferentia test cluster in staging. We can run a shadow benchmark alongside our NVIDIA nodes once this release stabilizes.', FALSE, 'Action Items Extraction & Costs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-101', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 2096, 2117, '34:56', 'On the analytics side, how are we capturing user satisfaction with the summaries?', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-102', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 2117, 2138, '35:17', 'Do we have thumbs up/thumbs down telemetry, or copy/share tracking?', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-103', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 2138, 2159, '35:38', 'We have three primary telemetry signals: copy-to-clipboard actions, share-clip creations, and inline thumbs-up/down feedback buttons on each summary section.', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-104', 'meeting-8p-60m', 'spk-8', 'Zoe Washington', 2159, 2180, '35:59', 'Our CS team will monitor those feedback signals weekly to flag any prompt drift or hallucination patterns.', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-105', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 2180, 2201, '36:20', 'Speaking of prompt drift, Maya, what is our guardrail against hallucinated action items or misattributed statements?', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-106', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 2201, 2222, '36:41', 'Every generated claim in the summary has a grounding citation pointing back to the transcript segment ID. If the model cannot provide a high-confidence citation span from the transcript, the claim is pruned.', TRUE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-107', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 2222, 2243, '37:02', 'That grounding verification happens in post-processing. It eliminates 99.7% of ungrounded hallucinations.', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-108', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 2243, 2264, '37:23', 'Grounding citations are also essential for legal defensibility. In corporate disputes, having an immutable link to what was actually uttered protects our clients.', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-109', 'meeting-8p-60m', 'spk-5', 'David Kalu', 2264, 2285, '37:44', 'What about disaster recovery? If an entire AWS region experiences a catastrophic outage, what is our RTO and RPO?', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-110', 'meeting-8p-60m', 'spk-5', 'David Kalu', 2285, 2306, '38:05', 'Recovery Time Objective is under five minutes via our automated DNS failover to the secondary region. Recovery Point Objective is zero for finalized meetings because records are synchronously replicated across regions.', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-111', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 2306, 2327, '38:26', 'For in-flight live meetings during a mid-call regional failure, the local client buffer replays the last 15 seconds to the new region, yielding an RPO of less than 2 seconds of audio.', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-112', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 2327, 2348, '38:47', 'That is industry-leading resilience. Very proud of this engineering achievement.', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-113', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 2348, 2369, '39:08', 'Let''s touch on mobile responsiveness and keyboard accessibility for the workspace.', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-114', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 2369, 2390, '39:29', 'Power users want to navigate transcripts with keyboard shortcuts: Space for Play/Pause, ''J'' to jump back 10 seconds, ''L'' to jump forward 10 seconds, and ''C'' to open the Clip modal.', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-115', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 2390, 2410, '39:50', 'All of those hotkeys are implemented on the window event listeners. We also ensured screen reader compatibility with ARIA live regions for streaming updates.', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-116', 'meeting-8p-60m', 'spk-8', 'Zoe Washington', 2410, 2431, '40:10', 'And on mobile or tablet screens, how does the layout adapt?', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-117', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 2431, 2452, '40:31', 'The workspace transitions from a side-by-side two-column view into a clean tabbed view where users can easily toggle between ''Transcript'', ''Summary'', and ''Action Items'' without horizontal scrolling.', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-118', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 2452, 2473, '40:52', 'Does the transcript search support fuzzy matching or regex?', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-119', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 2473, 2494, '41:13', 'Or is it semantic search across vector embeddings?', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-120', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 2494, 2515, '41:34', 'In the client, we have instant sub-millisecond keyword and prefix search across all speaker names and utterance texts.', FALSE, 'Grounding Citations & Resilience') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-121', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 2515, 2536, '41:55', 'In the global dashboard, we combine that with hybrid BM25 and vector semantic search, so you can search ''What did Maya say about VRAM?'' and find this exact conversation!', TRUE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-122', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 2536, 2557, '42:16', 'That is pure magic. That makes past meetings as searchable as code in GitHub.', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-123', 'meeting-8p-60m', 'spk-8', 'Zoe Washington', 2557, 2578, '42:37', 'Executives who miss meetings rely on that search constantly to catch up in three minutes instead of watching a 60-minute recording.', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-124', 'meeting-8p-60m', 'spk-5', 'David Kalu', 2578, 2599, '42:58', 'Let''s confirm the load testing numbers for Thursday''s rollout. What was our peak simulated concurrent users?', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-125', 'meeting-8p-60m', 'spk-5', 'David Kalu', 2599, 2620, '43:19', 'We simulated 10,000 concurrent streaming connections with 250 requests per second to the API gateway over a 4-hour soak test.', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-126', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 2620, 2641, '43:40', 'Memory leak tests showed flat RAM utilization across all worker pods. Zero zombie processes and garbage collection pauses stayed under 12 milliseconds.', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-127', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 2641, 2662, '44:01', 'Did the penetration test surface any vulnerabilities in our authentication tokens or clip sharing endpoints?', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-128', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 2662, 2683, '44:22', 'We reviewed the third-party pentest report from NCC Group. They found zero critical or high severity findings. Two low-severity items regarding HTTP headers were remediated on Monday.', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-129', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 2683, 2704, '44:43', 'We also verified rate limiting on the public clip endpoints to prevent automated scraping of customer video streams.', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-130', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 2704, 2725, '45:04', 'We are in an exceptionally strong position. Let''s do a round-robin check on our final deliverables and action items before we conclude.', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-131', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 2725, 2746, '45:25', 'Marcus, what is backend''s top priority before Thursday morning?', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-132', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 2746, 2767, '45:46', 'Backend will finalize the staging canary deployment configs, verify Route53 failover health check thresholds, and validate the Prometheus alert rules.', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-133', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 2767, 2788, '46:07', 'Maya, what is the AI team''s deliverable?', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-134', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 2788, 2809, '46:28', 'AI team will verify the grounding citation confidence threshold on the 70B model and deploy the quantized 8-bit diarization weights to the production image repository.', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-135', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 2809, 2830, '46:49', 'Elena, for Product Design?', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-136', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 2830, 2851, '47:10', 'Design will do a final pass on mobile breakpoints, ensure keyboard navigation tooltips are visible, and polish the simulated playback scrubber animations.', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-137', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 2851, 2872, '47:31', 'David, from SRE?', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-138', 'meeting-8p-60m', 'spk-5', 'David Kalu', 2872, 2893, '47:52', 'SRE will provision the warm idle GPU nodes in us-east-1 and us-west-2, verify cross-region database replication latency, and stand by during the canary rollout.', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-139', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 2893, 2914, '48:13', 'Priya, from Security and Compliance?', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-140', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 2914, 2935, '48:34', 'Security will review the final Terraform diffs for edge proxies, sign off on the PII redaction test results, and issue the formal SOC2 deployment authorization.', FALSE, 'Observability & Team Deliverables') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-141', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 2935, 2956, '48:55', 'Sam, for Data Platform?', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-142', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 2956, 2977, '49:16', 'Data team will monitor Kafka consumer lag during the canary ramp and verify that the automated memory zeroing assertions pass in all test suites.', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-143', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 2977, 2997, '49:37', 'And Zoe, from Customer Operations?', TRUE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-144', 'meeting-8p-60m', 'spk-8', 'Zoe Washington', 2997, 3018, '49:57', 'Ops will notify our top twenty enterprise pilot customers about the new 90-second summary turnaround guarantee and prepare help center documentation for the template switcher.', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-145', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 3018, 3039, '50:18', 'Alex, do we have an exact timeline for the canary progression on Thursday?', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-146', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 3039, 3060, '50:39', 'Yes: Thursday at 09:00 UTC, we route 5% of traffic to the new architecture. We monitor error rates and latency for two hours. At 11:00 UTC, we scale to 25%. By 15:00 UTC, if all metrics remain green, we complete the 100% rollout.', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-147', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 3060, 3081, '51:00', 'What are our automatic rollback triggers?', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-148', 'meeting-8p-60m', 'spk-5', 'David Kalu', 3081, 3102, '51:21', 'Automatic rollback triggers if P99 latency exceeds 600ms for more than 90 seconds, or if error rate surpasses 0.5% in any 60-second window.', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-149', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 3102, 3123, '51:42', 'If rollback occurs, does it disrupt active meetings or only new connections?', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-150', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 3123, 3144, '52:03', 'Active meetings stay pinned to their existing healthy nodes. New connections revert to the stable fallback cluster seamlessly.', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-151', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 3144, 3165, '52:24', 'That is an exceptionally safe deployment strategy. I give my full security approval.', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-152', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 3165, 3186, '52:45', 'Data integrity checks are also scheduled to run every 15 minutes during the ramp.', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-153', 'meeting-8p-60m', 'spk-8', 'Zoe Washington', 3186, 3207, '53:06', 'Our support team will have dedicated engineers on call in our Slack war room from 08:30 UTC onward.', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-154', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 3207, 3228, '53:27', 'Wonderful. We''ve covered every critical angle: performance, failover, security, UX, cost, and operational readiness.', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-155', 'meeting-8p-60m', 'spk-3', 'Marcus Thorne', 3228, 3249, '53:48', 'This has been one of the smoothest cross-functional architecture reviews we''ve run. Kudos to everyone for the thorough preparation.', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-156', 'meeting-8p-60m', 'spk-2', 'Dr. Maya Lin', 3249, 3270, '54:09', 'Excited to see these models perform in production at this scale. The latency drop will blow our users away.', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-157', 'meeting-8p-60m', 'spk-4', 'Elena Rostova', 3270, 3291, '54:30', 'And the UX will finally feel as fast and effortless as real human conversation.', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-158', 'meeting-8p-60m', 'spk-5', 'David Kalu', 3291, 3312, '54:51', 'Infrastructure is locked and ready. We have plenty of GPU capacity and resilient failovers.', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-159', 'meeting-8p-60m', 'spk-6', 'Priya Sharma', 3312, 3333, '55:12', 'Compliance documentation is filed and signed. All green on my end.', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-160', 'meeting-8p-60m', 'spk-7', 'Sam Chen', 3333, 3354, '55:33', 'Data pipeline monitors are configured and armed.', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-161', 'meeting-8p-60m', 'spk-8', 'Zoe Washington', 3354, 3375, '55:54', 'Enterprise customers are ready for the announcement.', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-8p-162', 'meeting-8p-60m', 'spk-1', 'Alex Vance', 3375, 3396, '56:15', 'Thank you all for an incredible sixty minutes. Let''s execute the Thursday deployment with precision. Have a great rest of your day!', FALSE, 'Rollout Timeline & Sign-Offs') ON CONFLICT (meeting_id, id) DO NOTHING;
