INSERT INTO public.highlights (id, meeting_id, title, quote, speaker_name, start_time, formatted_time, category) VALUES ('hl-ps-01', 'meeting-prod-sync', 'Haptic Feedback on Highlights', 'When the user drags the scrubber across an AI highlight, the subtle vibration makes the timeline feel tactile.', 'Elena Rostova', 720, '12:00', 'insight') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-ps-01', 'meeting-prod-sync', 'spk-1', 'Alex Vance', 0, 35, '00:00', 'Welcome everyone. Let''s look at the mobile scrubber designs Elena put together for Fathom 3.0.', FALSE, NULL) ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-ps-02', 'meeting-prod-sync', 'spk-4', 'Elena Rostova', 36, 80, '00:36', 'Thanks Alex. On smaller touchscreens, precise timeline scrubbing is traditionally painful. We created an adaptive zoom thumb that expands when held.', FALSE, NULL) ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-ps-03', 'meeting-prod-sync', 'spk-3', 'Marcus Thorne', 81, 125, '01:21', 'From a frontend performance perspective, rendering the audio waveform on HTML5 canvas keeps the frame rate locked at 60 frames per second.', FALSE, NULL) ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-ps-04', 'meeting-prod-sync', 'spk-8', 'Zoe Washington', 126, 170, '02:06', 'Field sales reps will love this. Being able to quickly scrub to the budget objection and cut a 20-second clip on an iPhone in an Uber is game changing.', FALSE, NULL) ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-ps-05', 'meeting-prod-sync', 'spk-4', 'Elena Rostova', 171, 220, '02:51', 'When the user drags the scrubber across an AI highlight, the subtle vibration makes the timeline feel tactile. We tested it with 10 beta users and they loved it.', FALSE, NULL) ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-ps-06', 'meeting-prod-sync', 'spk-1', 'Alex Vance', 221, 270, '03:41', 'Let''s lock that in. Elena please export the tokens and Marcus can wire up the canvas prototype by Wednesday.', FALSE, NULL) ON CONFLICT (meeting_id, id) DO NOTHING;
