INSERT INTO public.highlights (id, meeting_id, title, quote, speaker_name, start_time, formatted_time, category) VALUES ('hl-ac-01', 'meeting-sales-acme', '$180k Budget Allocation Confirmed', 'We have $180k approved in our Q4 budget specifically for meeting intelligence and Salesforce automation.', 'Sarah Jenkins', 540, '09:00', 'milestone') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-ac-01', 'meeting-sales-acme', 'spk-8', 'Zoe Washington', 0, 40, '00:00', 'Hi Sarah, thank you for joining us today. We''re excited to demonstrate Fathom''s enterprise capabilities for Acme Financial.', FALSE, NULL) ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-ac-02', 'meeting-sales-acme', 'spk-acme-1', 'Sarah Jenkins', 41, 95, '00:41', 'Thanks Zoe. Our 1,200 advisors currently spend almost 90 minutes each day documenting client conversations in Salesforce. We desperately need an automated solution.', FALSE, NULL) ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-ac-03', 'meeting-sales-acme', 'spk-1', 'Alex Vance', 96, 150, '01:36', 'Our Salesforce integration syncs key takeaways, action items, and regulatory disclaimers into Salesforce Financial Services Cloud in under two minutes.', FALSE, NULL) ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-ac-04', 'meeting-sales-acme', 'spk-acme-1', 'Sarah Jenkins', 151, 210, '02:31', 'We have $180k approved in our Q4 budget specifically for meeting intelligence and Salesforce automation, assuming your security credentials pass our CCO review.', FALSE, NULL) ON CONFLICT (meeting_id, id) DO NOTHING;
