INSERT INTO public.highlights (id, meeting_id, title, quote, speaker_name, start_time, formatted_time, category) VALUES ('hl-1on1-01', 'meeting-one-on-one', 'Design System Unification Approved', 'Let''s definitely dedicate 20% of design capacity in Q4 to unifiying the web and desktop design tokens.', 'Alex Vance', 420, '07:00', 'decision') ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-1on1-01', 'meeting-one-on-one', 'spk-1', 'Alex Vance', 0, 30, '00:00', 'Hey Elena, great to catch up today. How are you feeling after the big Fathom 3.0 review yesterday?', FALSE, NULL) ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-1on1-02', 'meeting-one-on-one', 'spk-4', 'Elena Rostova', 31, 80, '00:31', 'Feeling really energetic Alex. The feedback on the multi-column transcript workspace and instantaneous template switching was super validating.', FALSE, NULL) ON CONFLICT (meeting_id, id) DO NOTHING;
INSERT INTO public.transcript_segments (id, meeting_id, speaker_id, speaker_name, start_time, end_time, formatted_time, text, highlighted, topic) VALUES ('seg-1on1-03', 'meeting-one-on-one', 'spk-1', 'Alex Vance', 81, 130, '01:21', 'Let''s definitely dedicate 20% of design capacity in Q4 to unifiying the web and desktop design tokens. You''ve earned the autonomy to lead that initiative.', FALSE, NULL) ON CONFLICT (meeting_id, id) DO NOTHING;
